-- ============================================================================
-- Migration 1096: the Machining machines' fractional crews
-- ============================================================================
-- Generated by scripts/generate-machining-crews-migration.js; re-run it and diff instead of editing.
--
-- mhr_records.operators was smallint when the Machining machines were seeded (migrations 738 and 829): a crew of 0.25 (one operator tending
-- four CNC multi-spindles) was stored as 0, and 0.5 (one operator for two machines) as 1. Migration 971 made the column numeric(5,2) but
-- changed no value, and its restage script corrected the plastic presses only. So no labour was charged on a multi-spindle, and twice the
-- source's on a twin-spindle turning center and on the automated deburr cell.
--
-- Every machine of memory/machining/machine whose crew is a fraction, by name, on both locations' Machining rows (the India export,
-- memory/Countries data/India_XML_Data_.csv, states the same crews):
--   0.5   Default Automated Deburr (machiningusa.csv)
--   0.25  DMG Mori GMC25ISM-6 (simultaneous_turning_usa.csv)
--   0.5   Dooson Puma TT2500SY (simultaneous_turning_usa.csv)
--   0.5   HAAS DS-30Y (simultaneous_turning_usa.csv)
--   0.25  Index MS16C-6 (simultaneous_turning_usa.csv)
--   0.25  Index MS22-8 (simultaneous_turning_usa.csv)
--   0.25  Index MS32-6 (simultaneous_turning_usa.csv)
--   0.25  Index MS40-8 (simultaneous_turning_usa.csv)
--   0.5   Tsugami M08SY (simultaneous_turning_usa.csv)
--   0.25  Virtual CNC Multi-Spindle, 6 Spindles, Large (simultaneous_turning_usa.csv)
--   0.25  Virtual CNC Multi-Spindle, 6 Spindles, Small (simultaneous_turning_usa.csv)
--   0.25  Virtual CNC Multi-Spindle, 8 Spindles, Large (simultaneous_turning_usa.csv)
--   0.25  Virtual CNC Multi-Spindle, 8 Spindles, Small (simultaneous_turning_usa.csv)
--   0.5   Virtual CNC Turning Center with Sub Spindle, Large (simultaneous_turning_usa.csv)
--   0.5   Virtual CNC Turning Center with Sub Spindle, Medium (simultaneous_turning_usa.csv)
--   0.5   Virtual CNC Turning Center with Sub Spindle, Small (simultaneous_turning_usa.csv)
--
-- Only operators is written. Idempotent: the same values are re-set.
-- Verify: SELECT machine_name, location, operators FROM mhr_records WHERE process_group = 'Machining' AND operators <> round(operators) ORDER BY 1, 2;
-- ============================================================================

UPDATE mhr_records m SET operators = v.operators, updated_at = now()
FROM (VALUES
  ($str$Default Automated Deburr$str$, 0.5),
  ($str$DMG Mori GMC25ISM-6$str$, 0.25),
  ($str$Dooson Puma TT2500SY$str$, 0.5),
  ($str$HAAS DS-30Y$str$, 0.5),
  ($str$Index MS16C-6$str$, 0.25),
  ($str$Index MS22-8$str$, 0.25),
  ($str$Index MS32-6$str$, 0.25),
  ($str$Index MS40-8$str$, 0.25),
  ($str$Tsugami M08SY$str$, 0.5),
  ($str$Virtual CNC Multi-Spindle, 6 Spindles, Large$str$, 0.25),
  ($str$Virtual CNC Multi-Spindle, 6 Spindles, Small$str$, 0.25),
  ($str$Virtual CNC Multi-Spindle, 8 Spindles, Large$str$, 0.25),
  ($str$Virtual CNC Multi-Spindle, 8 Spindles, Small$str$, 0.25),
  ($str$Virtual CNC Turning Center with Sub Spindle, Large$str$, 0.5),
  ($str$Virtual CNC Turning Center with Sub Spindle, Medium$str$, 0.5),
  ($str$Virtual CNC Turning Center with Sub Spindle, Small$str$, 0.5)
) AS v(machine_name, operators)
WHERE m.process_group = 'Machining' AND m.machine_name = v.machine_name AND m.operators IS DISTINCT FROM v.operators;

DO $crew_check$
DECLARE wrong text[];
BEGIN
  SELECT array_agg(m.location || ': ' || m.machine_name || ' ' || COALESCE(m.operators::text, 'null') ORDER BY m.location, m.machine_name) INTO wrong
    FROM mhr_records m
    JOIN (VALUES
      ($str$Default Automated Deburr$str$, 0.5),
      ($str$DMG Mori GMC25ISM-6$str$, 0.25),
      ($str$Dooson Puma TT2500SY$str$, 0.5),
      ($str$HAAS DS-30Y$str$, 0.5),
      ($str$Index MS16C-6$str$, 0.25),
      ($str$Index MS22-8$str$, 0.25),
      ($str$Index MS32-6$str$, 0.25),
      ($str$Index MS40-8$str$, 0.25),
      ($str$Tsugami M08SY$str$, 0.5),
      ($str$Virtual CNC Multi-Spindle, 6 Spindles, Large$str$, 0.25),
      ($str$Virtual CNC Multi-Spindle, 6 Spindles, Small$str$, 0.25),
      ($str$Virtual CNC Multi-Spindle, 8 Spindles, Large$str$, 0.25),
      ($str$Virtual CNC Multi-Spindle, 8 Spindles, Small$str$, 0.25),
      ($str$Virtual CNC Turning Center with Sub Spindle, Large$str$, 0.5),
      ($str$Virtual CNC Turning Center with Sub Spindle, Medium$str$, 0.5),
      ($str$Virtual CNC Turning Center with Sub Spindle, Small$str$, 0.5)
    ) AS v(machine_name, operators) ON m.machine_name = v.machine_name
   WHERE m.process_group = 'Machining' AND m.operators IS DISTINCT FROM v.operators;
  IF wrong IS NOT NULL THEN RAISE EXCEPTION 'Machining machines whose crew still differs from memory/machining/machine: %', wrong; END IF;
END $crew_check$;

NOTIFY pgrst, 'reload schema';
